FILES['.env.example'] = '# Polymarket CLOB API Configuration\n# Base URL for the Polymarket CLOB API\nCLOB_API_URL=https://clob.polymarket.com\n\n# Your Polygon wallet private key (without 0x prefix)\n# NEVER commit your real private key to version control\nPRIVATE_KEY=your_private_key_here\n\n# Polygon chain ID (137 for mainnet, 80001 for Mumbai testnet)\nCHAIN_ID=137\n\n# Optional: API key for authenticated endpoints (obtained via /auth/api-key)\nCLOB_API_KEY=\nCLOB_API_SECRET=\nCLOB_API_PASSPHRASE=\n\n# Trading Configuration\n# Minimum profit percentage to consider an opportunity (e.g., 0.5 = 0.5%)\nMIN_PROFIT_PCT=0.5\n\n# Maximum position size as percentage of portfolio (e.g., 5 = 5%)\nMAX_POSITION_PCT=5.0\n\n# Maximum total exposure as percentage of portfolio (e.g., 50 = 50%)\nMAX_EXPOSURE_PCT=50.0\n\n# Maximum number of concurrent open positions\nMAX_CONCURRENT_POSITIONS=10\n\n# Polymarket fee rate (approximately 2% total)\nFEE_RATE=0.02\n\n# Mock Mode - set to true to run without real funds using simulated data\nMOCK_MODE=true\n\n# Dashboard Configuration\nDASHBOARD_PORT=8080\nDASHBOARD_HOST=0.0.0.0\n\n# Database path\nDATABASE_URL=sqlite+aiosqlite:///./polymarket_bot.db\n\n# Logging level (DEBUG, INFO, WARNING, ERROR)\nLOG_LEVEL=INFO\n\n# Scan interval in seconds\nSCAN_INTERVAL=30\n\n# Initial portfolio value in USDC (for mock mode)\nINITIAL_PORTFOLIO=1000.0\n'

FILES['bot/__init__.py'] = ''

FILES['bot/arbitrage_detector.py'] = '"""\nArbitrage detector for Polymarket Arbitrage Bot.\n\nStrategy: YES/NO Sum Arbitrage\n  - If cost_to_buy_YES + cost_to_buy_NO < 1.0 - fees, one of the tokens will\n    resolve to $1 and the other to $0, guaranteeing a profit on the combined\n    position regardless of market outcome.\n\n  Net cost  = yes_ask + no_ask\n  Net revenue on resolution = $1.00 (winner) + $0.00 (loser)\n  Gross profit per unit = 1.0 - net_cost\n  Net profit per unit   = gross_profit - fees (= net_cost * fee_rate)\n                        = 1.0 - yes_ask - no_ask - (yes_ask + no_ask) * fee_rate\n"""\n\nimport logging\nimport math\nfrom dataclasses import dataclass, field\nfrom typing import List, Optional\n\nfrom bot.client import MarketPrice\nfrom config import config\n\nlogger = logging.getLogger(__name__)\n\n\n@dataclass\nclass ArbitrageOpportunity:\n    """Encapsulates a detected YES/NO sum arbitrage opportunity."""\n\n    market_id: str\n    question: str\n    yes_token_id: str\n    no_token_id: str\n    yes_price: float           # ask price for YES (cost to buy)\n    no_price: float            # ask price for NO (cost to buy)\n    net_cost: float            # yes_price + no_price\n    fees: float                # estimated fees on the combined position\n    gross_profit_per_unit: float   # 1.0 - net_cost\n    net_profit_per_unit: float     # gross_profit - fees\n    profit_pct: float          # net_profit / net_cost * 100\n    spread: float              # 1.0 - yes_price - no_price  (pre-fee gap)\n    recommended_size: float    # recommended position size in USD\n    kelly_fraction: float      # raw Kelly fraction used\n    volume_24h: float = 0.0\n\n    def as_dict(self) -> dict:\n        return {\n            "market_id": self.market_id,\n            "question": self.question,\n            "yes_token_id": self.yes_token_id,\n            "no_token_id": self.no_token_id,\n            "yes_price": round(self.yes_price, 4),\n            "no_price": round(self.no_price, 4),\n            "net_cost": round(self.net_cost, 4),\n            "fees": round(self.fees, 6),\n            "gross_profit_per_unit": round(self.gross_profit_per_unit, 6),\n            "net_profit_per_unit": round(self.net_profit_per_unit, 6),\n            "profit_pct": round(self.profit_pct, 4),\n            "spread": round(self.spread, 4),\n            "recommended_size": round(self.recommended_size, 2),\n            "kelly_fraction": round(self.kelly_fraction, 6),\n            "volume_24h": round(self.volume_24h, 2),\n        }\n\n\nclass ArbitrageDetector:\n    """\n    Scans a list of MarketPrice objects and identifies YES/NO sum arbitrage\n    opportunities that meet the configured profit threshold.\n    """\n\n    def __init__(\n        self,\n        fee_rate: float = None,\n        min_profit_pct: float = None,\n        kelly_fraction: float = None,\n        portfolio_value: float = None,\n        max_position_pct: float = None,\n    ):\n        self.fee_rate = fee_rate if fee_rate is not None else config.FEE_RATE\n        self.min_profit_pct = min_profit_pct if min_profit_pct is not None else config.MIN_PROFIT_PCT\n        self.kelly_fraction = kelly_fraction if kelly_fraction is not None else config.KELLY_FRACTION\n        self.portfolio_value = portfolio_value if portfolio_value is not None else config.INITIAL_PORTFOLIO\n        self.max_position_pct = max_position_pct if max_position_pct is not None else config.MAX_POSITION_PCT\n\n    # ─── Public API ───────────────────────────────────────────────────────────\n\n    def detect(self, markets: List[MarketPrice]) -> List[ArbitrageOpportunity]:\n        """\n        Check each market for YES/NO sum arbitrage.\n        Returns opportunities sorted by descending net profit percentage.\n        """\n        opportunities: List[ArbitrageOpportunity] = []\n\n        for market in markets:\n            opp = self._check_market(market)\n            if opp is not None:\n                opportunities.append(opp)\n\n        opportunities.sort(key=lambda o: o.profit_pct, reverse=True)\n\n        if opportunities:\n            logger.info(\n                "Detected %d arbitrage opportunity(ies). Best: %.4f%% profit on \'%s\'",\n                len(opportunities),\n                opportunities[0].profit_pct,\n                opportunities[0].question[:60],\n            )\n        return opportunities\n\n    def update_portfolio_value(self, value: float) -> None:\n        """Update the portfolio value used for position sizing."""\n        self.portfolio_value = max(value, 1.0)\n\n    # ─── Internal helpers ─────────────────────────────────────────────────────\n\n    def _check_market(self, m: MarketPrice) -> Optional[ArbitrageOpportunity]:\n        """Return an ArbitrageOpportunity if one exists for this market, else None."""\n        yes_ask = m.yes_ask\n        no_ask = m.no_ask\n\n        if yes_ask <= 0 or no_ask <= 0:\n            return None\n        if yes_ask >= 1.0 or no_ask >= 1.0:\n            return None\n\n        net_cost = yes_ask + no_ask\n        spread = 1.0 - net_cost  # positive → raw gap before fees\n\n        # Fees apply to the total capital deployed (both legs)\n        fees = net_cost * self.fee_rate\n\n        gross_profit = 1.0 - net_cost   # revenue ($1) minus cost\n        net_profit = gross_profit - fees\n\n        # Profit as a percentage of capital deployed\n        profit_pct = (net_profit / net_cost) * 100.0\n\n        if profit_pct < self.min_profit_pct:\n            return None\n\n        # ── Kelly criterion position sizing ───────────────────────────────────\n        # For a "bet" with probability p of winning and net odds b:\n        #   p = probability of winning one leg (= 1.0, arb is risk-free)\n        #   b = net_profit / net_cost  (fractional gain)\n        # Kelly = (p * b - (1 - p)) / b  → for a risk-free arb, Kelly = 1.0\n        # We then scale by KELLY_FRACTION and cap at MAX_POSITION_PCT.\n        b = net_profit / net_cost  # fractional return per unit invested\n        kelly_raw = min(b, 1.0)    # risk-free → full Kelly, but cap at 1\n\n        max_position = self.portfolio_value * (self.max_position_pct / 100.0)\n        kelly_position = self.portfolio_value * self.kelly_fraction * kelly_raw\n        recommended_size = min(kelly_position, max_position)\n        recommended_size = max(recommended_size, 1.0)   # at least $1\n\n        logger.debug(\n            "Opportunity: %s | YES=%.4f NO=%.4f spread=%.4f profit=%.4f%%",\n            m.market_id, yes_ask, no_ask, spread, profit_pct,\n        )\n\n        return ArbitrageOpportunity(\n            market_id=m.market_id,\n            question=m.question,\n            yes_token_id=m.yes_token_id,\n            no_token_id=m.no_token_id,\n            yes_price=yes_ask,\n            no_price=no_ask,\n            net_cost=net_cost,\n            fees=fees,\n            gross_profit_per_unit=gross_profit,\n            net_profit_per_unit=net_profit,\n            profit_pct=profit_pct,\n            spread=spread,\n            recommended_size=round(recommended_size, 2),\n            kelly_fraction=kelly_raw,\n            volume_24h=m.volume_24h,\n        )\n'

FILES['bot/client.py'] = '"""\nPolymarket CLOB client wrapper.\nSupports both real trading (via py_clob_client) and mock mode for testing.\n"""\n\nimport asyncio\nimport logging\nimport random\nimport time\nfrom dataclasses import dataclass, field\nfrom typing import Optional\n\nfrom config import config\n\nlogger = logging.getLogger(__name__)\n\nMOCK_MARKET_QUESTIONS = [\n    "Will the Fed raise rates in Q1 2026?",\n    "Will Bitcoin reach $150,000 by end of 2026?",\n    "Will the US enter a recession in 2026?",\n    "Will Ethereum 2.0 launch by mid-2026?",\n    "Will the S&P 500 end 2026 above 6000?",\n    "Will there be a US government shutdown in 2026?",\n    "Will inflation drop below 2% by mid-2026?",\n    "Will Nvidia stock split in 2026?",\n    "Will the US elect a new president in 2028?",\n    "Will OpenAI release GPT-5 in 2026?",\n    "Will Tesla launch its robotaxi by Q3 2026?",\n    "Will China invade Taiwan in 2026?",\n    "Will gold hit $3500 by end of 2026?",\n    "Will oil prices exceed $100/barrel in 2026?",\n    "Will SpaceX land humans on Mars by 2030?",\n    "Will the EU ban TikTok in 2026?",\n    "Will Meta release AR glasses by Q2 2026?",\n    "Will unemployment in the US exceed 5% in 2026?",\n    "Will Amazon acquire another major company in 2026?",\n    "Will quantum computing achieve supremacy by 2027?",\n]\n\n\n@dataclass\nclass MarketPrice:\n    """YES and NO token prices for a market."""\n    market_id: str\n    question: str\n    yes_token_id: str\n    no_token_id: str\n    yes_ask: float   # Best ask price for YES (what we\'d pay to buy YES)\n    no_ask: float    # Best ask price for NO (what we\'d pay to buy NO)\n    yes_bid: float   # Best bid (what we\'d receive selling YES)\n    no_bid: float    # Best bid (what we\'d receive selling NO)\n    volume_24h: float = 0.0\n    end_date: Optional[str] = None\n\n\n@dataclass\nclass OrderResult:\n    """Result from placing an order."""\n    order_id: str\n    market_id: str\n    token_id: str\n    side: str        # "BUY" or "SELL"\n    price: float\n    size: float\n    status: str      # "MATCHED", "LIVE", "CANCELLED"\n    filled_size: float = 0.0\n    fees_paid: float = 0.0\n\n\nclass MockPolymarketClient:\n    """\n    Simulated Polymarket client for testing without real funds.\n    Generates realistic market data with occasional arbitrage opportunities.\n    """\n\n    def __init__(self):\n        self._markets: dict[str, MarketPrice] = {}\n        self._balance = config.INITIAL_PORTFOLIO\n        self._order_counter = 0\n        self._init_mock_markets()\n        logger.info(f"[MOCK] Client initialized with ${self._balance:.2f} USDC balance")\n\n    def _init_mock_markets(self):\n        for i, question in enumerate(MOCK_MARKET_QUESTIONS):\n            market_id = f"mock-market-{i:03d}"\n            # Random fair prices that roughly sum to 1.0\n            yes_mid = round(random.uniform(0.10, 0.90), 3)\n            no_mid = round(1.0 - yes_mid, 3)\n            spread = random.uniform(0.005, 0.015)\n            self._markets[market_id] = MarketPrice(\n                market_id=market_id,\n                question=question,\n                yes_token_id=f"yes-token-{i:03d}",\n                no_token_id=f"no-token-{i:03d}",\n                yes_ask=round(min(yes_mid + spread / 2, 0.99), 4),\n                no_ask=round(min(no_mid + spread / 2, 0.99), 4),\n                yes_bid=round(max(yes_mid - spread / 2, 0.01), 4),\n                no_bid=round(max(no_mid - spread / 2, 0.01), 4),\n                volume_24h=round(random.uniform(1_000, 500_000), 2),\n            )\n\n    def _drift_markets(self):\n        """Randomly drift prices to simulate live market movement."""\n        for market_id, mp in self._markets.items():\n            # Occasionally introduce a real arbitrage opportunity (~5% chance)\n            if random.random() < 0.05:\n                gap = random.uniform(0.008, 0.04)\n                yes_ask = round(random.uniform(0.10, 0.90), 3)\n                no_ask = round(1.0 - yes_ask - gap, 3)\n                no_ask = max(0.01, min(0.99, no_ask))\n                spread = random.uniform(0.003, 0.010)\n                self._markets[market_id] = MarketPrice(\n                    market_id=market_id,\n                    question=mp.question,\n                    yes_token_id=mp.yes_token_id,\n                    no_token_id=mp.no_token_id,\n                    yes_ask=round(yes_ask, 4),\n                    no_ask=round(no_ask, 4),\n                    yes_bid=round(yes_ask - spread, 4),\n                    no_bid=round(no_ask - spread, 4),\n                    volume_24h=mp.volume_24h,\n                )\n            else:\n                # Normal drift\n                drift = random.uniform(-0.005, 0.005)\n                yes_ask = max(0.01, min(0.99, mp.yes_ask + drift))\n                no_ask = max(0.01, min(0.99, mp.no_ask - drift))\n                spread_y = mp.yes_ask - mp.yes_bid\n                spread_n = mp.no_ask - mp.no_bid\n                self._markets[market_id] = MarketPrice(\n                    market_id=market_id,\n                    question=mp.question,\n                    yes_token_id=mp.yes_token_id,\n                    no_token_id=mp.no_token_id,\n                    yes_ask=round(yes_ask, 4),\n                    no_ask=round(no_ask, 4),\n                    yes_bid=round(max(0.01, yes_ask - spread_y), 4),\n                    no_bid=round(max(0.01, no_ask - spread_n), 4),\n                    volume_24h=mp.volume_24h,\n                )\n\n    async def get_markets(self) -> list[MarketPrice]:\n        """Return all simulated markets."""\n        await asyncio.sleep(0.05)  # simulate network latency\n        self._drift_markets()\n        return list(self._markets.values())\n\n    async def get_balance(self) -> float:\n        """Return simulated USDC balance."""\n        await asyncio.sleep(0.02)\n        return self._balance\n\n    async def place_order(\n        self,\n        market_id: str,\n        token_id: str,\n        side: str,\n        price: float,\n        size: float,\n    ) -> OrderResult:\n        """Simulate placing an order (always fills immediately in mock mode)."""\n        await asyncio.sleep(random.uniform(0.05, 0.15))\n        self._order_counter += 1\n        order_id = f"mock-order-{self._order_counter:06d}-{int(time.time())}"\n        fees = size * price * config.FEE_RATE\n\n        if side == "BUY":\n            cost = size * price + fees\n            if cost > self._balance:\n                logger.warning(f"[MOCK] Insufficient balance: need ${cost:.2f}, have ${self._balance:.2f}")\n                return OrderResult(\n                    order_id=order_id,\n                    market_id=market_id,\n                    token_id=token_id,\n                    side=side,\n                    price=price,\n                    size=size,\n                    status="CANCELLED",\n                    filled_size=0.0,\n                    fees_paid=0.0,\n                )\n            self._balance -= cost\n        else:\n            proceeds = size * price - fees\n            self._balance += proceeds\n\n        logger.debug(\n            f"[MOCK] Order {order_id}: {side} {size} tokens @ ${price:.4f} "\n            f"(fees ${fees:.4f}) | balance=${self._balance:.2f}"\n        )\n        return OrderResult(\n            order_id=order_id,\n            market_id=market_id,\n            token_id=token_id,\n            side=side,\n            price=price,\n            size=size,\n            status="MATCHED",\n            filled_size=size,\n            fees_paid=fees,\n        )\n\n    async def resolve_position(self, market_id: str, winning_token_id: str, size: float) -> float:\n        """Simulate market resolution - winning side pays $1 per token."""\n        payout = size * 1.0\n        self._balance += payout\n        logger.info(f"[MOCK] Market {market_id} resolved. Payout: ${payout:.2f}")\n        return payout\n\n\nclass LivePolymarketClient:\n    """\n    Real Polymarket CLOB client.\n    Uses py_clob_client for authenticated trading on Polygon.\n    """\n\n    def __init__(self):\n        try:\n            from py_clob_client.client import ClobClient\n            from py_clob_client.clob_types import ApiCreds\n\n            creds = None\n            if config.CLOB_API_KEY:\n                creds = ApiCreds(\n                    api_key=config.CLOB_API_KEY,\n                    api_secret=config.CLOB_API_SECRET,\n                    api_passphrase=config.CLOB_API_PASSPHRASE,\n                )\n\n            self._client = ClobClient(\n                host=config.CLOB_API_URL,\n                chain_id=config.CHAIN_ID,\n                key=config.PRIVATE_KEY,\n                creds=creds,\n            )\n            logger.info("Live Polymarket CLOB client initialized.")\n        except ImportError:\n            raise RuntimeError(\n                "py_clob_client not installed. Run: pip install py-clob-client"\n            )\n\n    async def get_markets(self) -> list[MarketPrice]:\n        """Fetch active binary markets from Polymarket CLOB."""\n        loop = asyncio.get_event_loop()\n        try:\n            raw = await loop.run_in_executor(None, self._client.get_markets)\n        except Exception as e:\n            logger.error(f"Failed to fetch markets: {e}")\n            return []\n\n        markets = []\n        for m in raw.get("data", []):\n            try:\n                tokens = m.get("tokens", [])\n                if len(tokens) < 2:\n                    continue\n                yes_token = next((t for t in tokens if t.get("outcome") == "Yes"), None)\n                no_token = next((t for t in tokens if t.get("outcome") == "No"), None)\n                if not yes_token or not no_token:\n                    continue\n\n                yes_book = await loop.run_in_executor(\n                    None, self._client.get_order_book, yes_token["token_id"]\n                )\n                no_book = await loop.run_in_executor(\n                    None, self._client.get_order_book, no_token["token_id"]\n                )\n\n                yes_ask = float(yes_book.asks[0].price) if yes_book.asks else 0.99\n                no_ask = float(no_book.asks[0].price) if no_book.asks else 0.99\n                yes_bid = float(yes_book.bids[0].price) if yes_book.bids else 0.01\n                no_bid = float(no_book.bids[0].price) if no_book.bids else 0.01\n\n                markets.append(MarketPrice(\n                    market_id=m["condition_id"],\n                    question=m.get("question", "Unknown"),\n                    yes_token_id=yes_token["token_id"],\n                    no_token_id=no_token["token_id"],\n                    yes_ask=yes_ask,\n                    no_ask=no_ask,\n                    yes_bid=yes_bid,\n                    no_bid=no_bid,\n                    volume_24h=float(m.get("volume24hr", 0)),\n                ))\n            except Exception as e:\n                logger.debug(f"Skipping market {m.get(\'condition_id\', \'?\')}: {e}")\n                continue\n\n        logger.info(f"Fetched {len(markets)} live markets.")\n        return markets\n\n    async def get_balance(self) -> float:\n        """Return USDC balance from the wallet."""\n        loop = asyncio.get_event_loop()\n        try:\n            bal = await loop.run_in_executor(None, self._client.get_balance)\n            return float(bal)\n        except Exception as e:\n            logger.error(f"Failed to fetch balance: {e}")\n            return 0.0\n\n    async def place_order(\n        self,\n        market_id: str,\n        token_id: str,\n        side: str,\n        price: float,\n        size: float,\n    ) -> OrderResult:\n        """Place a limit order on Polymarket CLOB."""\n        from py_clob_client.clob_types import OrderArgs, Side as ClobSide\n\n        loop = asyncio.get_event_loop()\n        try:\n            order_args = OrderArgs(\n                token_id=token_id,\n                price=price,\n                size=size,\n                side=ClobSide.BUY if side == "BUY" else ClobSide.SELL,\n            )\n            resp = await loop.run_in_executor(\n                None, self._client.create_and_post_order, order_args\n            )\n            order_id = resp.get("orderID", "unknown")\n            status = resp.get("status", "LIVE")\n            filled = float(resp.get("sizeMatched", 0))\n            fees = filled * price * config.FEE_RATE\n            return OrderResult(\n                order_id=order_id,\n                market_id=market_id,\n                token_id=token_id,\n                side=side,\n                price=price,\n                size=size,\n                status=status,\n                filled_size=filled,\n                fees_paid=fees,\n            )\n        except Exception as e:\n            logger.error(f"Order placement failed: {e}")\n            return OrderResult(\n                order_id="error",\n                market_id=market_id,\n                token_id=token_id,\n                side=side,\n                price=price,\n                size=size,\n                status="CANCELLED",\n                filled_size=0.0,\n                fees_paid=0.0,\n            )\n\n\ndef create_client():\n    """Factory: returns mock or live client based on config."""\n    if config.MOCK_MODE:\n        logger.info("Running in MOCK mode. No real funds will be used.")\n        return MockPolymarketClient()\n    else:\n        logger.info("Running in LIVE mode. Real funds will be used!")\n        return LivePolymarketClient()\n'

FILES['bot/database.py'] = '"""\nDatabase module for Polymarket Arbitrage Bot.\nUses SQLAlchemy with async SQLite backend.\n"""\n\nimport logging\nfrom datetime import datetime\nfrom typing import Optional, List\n\nfrom sqlalchemy import (\n    Column,\n    Integer,\n    String,\n    Float,\n    Boolean,\n    DateTime,\n    Text,\n    select,\n    desc,\n    func,\n)\nfrom sqlalchemy.ext.asyncio import AsyncSession, create_async_engine, async_sessionmaker\nfrom sqlalchemy.orm import DeclarativeBase\n\nfrom config import config\n\nlogger = logging.getLogger(__name__)\n\n\nclass Base(DeclarativeBase):\n    pass\n\n\nclass Opportunity(Base):\n    """Detected arbitrage opportunities."""\n\n    __tablename__ = "opportunities"\n\n    id = Column(Integer, primary_key=True, index=True)\n    market_id = Column(String(255), nullable=False, index=True)\n    question = Column(Text, nullable=False)\n    yes_price = Column(Float, nullable=False)\n    no_price = Column(Float, nullable=False)\n    spread = Column(Float, nullable=False)\n    potential_profit_pct = Column(Float, nullable=False)\n    detected_at = Column(DateTime, default=datetime.utcnow, nullable=False)\n    executed = Column(Boolean, default=False, nullable=False)\n    trade_id = Column(Integer, nullable=True)\n\n\nclass Trade(Base):\n    """Executed trades."""\n\n    __tablename__ = "trades"\n\n    id = Column(Integer, primary_key=True, index=True)\n    market_id = Column(String(255), nullable=False, index=True)\n    question = Column(Text, nullable=False)\n    strategy = Column(String(50), nullable=False, default="yes_no_arb")\n    yes_size = Column(Float, nullable=False)\n    no_size = Column(Float, nullable=False)\n    yes_price = Column(Float, nullable=False)\n    no_price = Column(Float, nullable=False)\n    total_cost = Column(Float, nullable=False)\n    expected_profit = Column(Float, nullable=False)\n    actual_profit = Column(Float, nullable=True)\n    status = Column(String(20), nullable=False, default="open")  # open/closed/cancelled\n    opened_at = Column(DateTime, default=datetime.utcnow, nullable=False)\n    closed_at = Column(DateTime, nullable=True)\n\n\nclass BotStats(Base):\n    """Periodic bot performance snapshots."""\n\n    __tablename__ = "bot_stats"\n\n    id = Column(Integer, primary_key=True, index=True)\n    timestamp = Column(DateTime, default=datetime.utcnow, nullable=False)\n    total_pnl = Column(Float, nullable=False, default=0.0)\n    total_trades = Column(Integer, nullable=False, default=0)\n    winning_trades = Column(Integer, nullable=False, default=0)\n    portfolio_value = Column(Float, nullable=False, default=0.0)\n    opportunities_found = Column(Integer, nullable=False, default=0)\n\n\n# Engine and session factory (initialized on startup)\n_engine = None\n_async_session: Optional[async_sessionmaker] = None\n\n\nasync def init_database() -> None:\n    """Initialize the database, creating tables if they don\'t exist."""\n    global _engine, _async_session\n\n    db_url = config.DATABASE_URL\n    logger.info(f"Initializing database at: {db_url}")\n\n    _engine = create_async_engine(\n        db_url,\n        echo=False,\n        future=True,\n        connect_args={"check_same_thread": False},\n    )\n\n    _async_session = async_sessionmaker(\n        _engine, class_=AsyncSession, expire_on_commit=False\n    )\n\n    async with _engine.begin() as conn:\n        await conn.run_sync(Base.metadata.create_all)\n\n    logger.info("Database initialized successfully.")\n\n\ndef get_session() -> AsyncSession:\n    """Get a new async database session."""\n    if _async_session is None:\n        raise RuntimeError("Database not initialized. Call init_database() first.")\n    return _async_session()\n\n\nasync def save_opportunity(\n    market_id: str,\n    question: str,\n    yes_price: float,\n    no_price: float,\n    spread: float,\n    potential_profit_pct: float,\n) -> int:\n    """Persist a detected arbitrage opportunity. Returns the new record ID."""\n    async with get_session() as session:\n        opp = Opportunity(\n            market_id=market_id,\n            question=question,\n            yes_price=yes_price,\n            no_price=no_price,\n            spread=spread,\n            potential_profit_pct=potential_profit_pct,\n            detected_at=datetime.utcnow(),\n            executed=False,\n        )\n        session.add(opp)\n        await session.commit()\n        await session.refresh(opp)\n        return opp.id\n\n\nasync def mark_opportunity_executed(opportunity_id: int, trade_id: int) -> None:\n    """Mark an opportunity as executed with its corresponding trade ID."""\n    async with get_session() as session:\n        result = await session.execute(\n            select(Opportunity).where(Opportunity.id == opportunity_id)\n        )\n        opp = result.scalar_one_or_none()\n        if opp:\n            opp.executed = True\n            opp.trade_id = trade_id\n            await session.commit()\n\n\nasync def save_trade(\n    market_id: str,\n    question: str,\n    strategy: str,\n    yes_size: float,\n    no_size: float,\n    yes_price: float,\n    no_price: float,\n    total_cost: float,\n    expected_profit: float,\n) -> int:\n    """Persist a new trade record. Returns the new trade ID."""\n    async with get_session() as session:\n        trade = Trade(\n            market_id=market_id,\n            question=question,\n            strategy=strategy,\n            yes_size=yes_size,\n            no_size=no_size,\n            yes_price=yes_price,\n            no_price=no_price,\n            total_cost=total_cost,\n            expected_profit=expected_profit,\n            status="open",\n            opened_at=datetime.utcnow(),\n        )\n        session.add(trade)\n        await session.commit()\n        await session.refresh(trade)\n        return trade.id\n\n\nasync def close_trade(trade_id: int, actual_profit: float, status: str = "closed") -> None:\n    """Update a trade with its final profit and closed status."""\n    async with get_session() as session:\n        result = await session.execute(select(Trade).where(Trade.id == trade_id))\n        trade = result.scalar_one_or_none()\n        if trade:\n            trade.actual_profit = actual_profit\n            trade.status = status\n            trade.closed_at = datetime.utcnow()\n            await session.commit()\n\n\nasync def save_bot_stats(\n    total_pnl: float,\n    total_trades: int,\n    winning_trades: int,\n    portfolio_value: float,\n    opportunities_found: int,\n) -> None:\n    """Snapshot current bot stats."""\n    async with get_session() as session:\n        stats = BotStats(\n            timestamp=datetime.utcnow(),\n            total_pnl=total_pnl,\n            total_trades=total_trades,\n            winning_trades=winning_trades,\n            portfolio_value=portfolio_value,\n            opportunities_found=opportunities_found,\n        )\n        session.add(stats)\n        await session.commit()\n\n\nasync def get_recent_opportunities(limit: int = 50) -> List[dict]:\n    """Fetch the most recent arbitrage opportunities."""\n    async with get_session() as session:\n        result = await session.execute(\n            select(Opportunity).order_by(desc(Opportunity.detected_at)).limit(limit)\n        )\n        rows = result.scalars().all()\n        return [\n            {\n                "id": r.id,\n                "market_id": r.market_id,\n                "question": r.question,\n                "yes_price": r.yes_price,\n                "no_price": r.no_price,\n                "spread": r.spread,\n                "potential_profit_pct": r.potential_profit_pct,\n                "detected_at": r.detected_at.isoformat() if r.detected_at else None,\n                "executed": r.executed,\n                "trade_id": r.trade_id,\n            }\n            for r in rows\n        ]\n\n\nasync def get_trades(limit: int = 100) -> List[dict]:\n    """Fetch trade history, most recent first."""\n    async with get_session() as session:\n        result = await session.execute(\n            select(Trade).order_by(desc(Trade.opened_at)).limit(limit)\n        )\n        rows = result.scalars().all()\n        return [\n            {\n                "id": r.id,\n                "market_id": r.market_id,\n                "question": r.question,\n                "strategy": r.strategy,\n                "yes_size": r.yes_size,\n                "no_size": r.no_size,\n                "yes_price": r.yes_price,\n                "no_price": r.no_price,\n                "total_cost": r.total_cost,\n                "expected_profit": r.expected_profit,\n                "actual_profit": r.actual_profit,\n                "status": r.status,\n                "opened_at": r.opened_at.isoformat() if r.opened_at else None,\n                "closed_at": r.closed_at.isoformat() if r.closed_at else None,\n            }\n            for r in rows\n        ]\n\n\nasync def get_open_trades() -> List[dict]:\n    """Fetch currently open positions."""\n    async with get_session() as session:\n        result = await session.execute(\n            select(Trade).where(Trade.status == "open").order_by(desc(Trade.opened_at))\n        )\n        rows = result.scalars().all()\n        return [\n            {\n                "id": r.id,\n                "market_id": r.market_id,\n                "question": r.question,\n                "strategy": r.strategy,\n                "yes_size": r.yes_size,\n                "no_size": r.no_size,\n                "yes_price": r.yes_price,\n                "no_price": r.no_price,\n                "total_cost": r.total_cost,\n                "expected_profit": r.expected_profit,\n                "opened_at": r.opened_at.isoformat() if r.opened_at else None,\n            }\n            for r in rows\n        ]\n\n\nasync def get_latest_stats() -> Optional[dict]:\n    """Fetch the most recent bot stats snapshot."""\n    async with get_session() as session:\n        result = await session.execute(\n            select(BotStats).order_by(desc(BotStats.timestamp)).limit(1)\n        )\n        row = result.scalar_one_or_none()\n        if not row:\n            return None\n        return {\n            "id": row.id,\n            "timestamp": row.timestamp.isoformat() if row.timestamp else None,\n            "total_pnl": row.total_pnl,\n            "total_trades": row.total_trades,\n            "winning_trades": row.winning_trades,\n            "portfolio_value": row.portfolio_value,\n            "opportunities_found": row.opportunities_found,\n        }\n\n\nasync def get_stats_history(limit: int = 100) -> List[dict]:\n    """Fetch historical stats for chart rendering."""\n    async with get_session() as session:\n        result = await session.execute(\n            select(BotStats).order_by(desc(BotStats.timestamp)).limit(limit)\n        )\n        rows = result.scalars().all()\n        # Return in chronological order for chart plotting\n        return [\n            {\n                "timestamp": r.timestamp.isoformat() if r.timestamp else None,\n                "total_pnl": r.total_pnl,\n                "portfolio_value": r.portfolio_value,\n                "opportunities_found": r.opportunities_found,\n                "total_trades": r.total_trades,\n            }\n            for r in reversed(rows)\n        ]\n\n\nasync def count_opportunities_today() -> int:\n    """Count opportunities detected today."""\n    async with get_session() as session:\n        today = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)\n        result = await session.execute(\n            select(func.count(Opportunity.id)).where(Opportunity.detected_at >= today)\n        )\n        return result.scalar() or 0\n'

FILES['bot/engine.py'] = '"""\nMain bot engine for Polymarket Arbitrage Bot.\nOrchestrates scanner → detector → risk manager → trader.\nRuns the main async loop and pushes events to the dashboard via asyncio.Queue.\n"""\n\nimport asyncio\nimport logging\nimport time\nfrom typing import Any, Dict, Optional\n\nfrom bot import database as db\nfrom bot.arbitrage_detector import ArbitrageDetector, ArbitrageOpportunity\nfrom bot.risk_manager import RiskManager\nfrom bot.scanner import MarketScanner\nfrom bot.trader import Trader\nfrom config import config\n\nlogger = logging.getLogger(__name__)\n\n\nclass BotEngine:\n    """\n    Coordinates all bot components and drives the main scan-detect-trade loop.\n    """\n\n    def __init__(self, event_queue: Optional[asyncio.Queue] = None):\n        self.scanner = MarketScanner(cache_ttl=config.SCAN_INTERVAL // 2)\n        self.detector = ArbitrageDetector()\n        self.risk_manager = RiskManager()\n        self.trader = Trader()\n        self.event_queue: asyncio.Queue = event_queue or asyncio.Queue(maxsize=500)\n\n        self._running: bool = False\n        self._loop_task: Optional[asyncio.Task] = None\n        self._stats_task: Optional[asyncio.Task] = None\n        self._start_time: Optional[float] = None\n\n        # Cumulative counters\n        self._opportunities_found: int = 0\n        self._total_trades_opened: int = 0\n        self._winning_trades: int = 0\n\n    # ─── Lifecycle ────────────────────────────────────────────────────────────\n\n    async def start(self) -> None:\n        if self._running:\n            logger.warning("Engine already running.")\n            return\n        self._running = True\n        self._start_time = time.time()\n        logger.info("Bot engine starting…")\n        self._loop_task = asyncio.create_task(self._main_loop(), name="bot_main_loop")\n        self._stats_task = asyncio.create_task(self._stats_loop(), name="bot_stats_loop")\n        await self._emit_event("status", {"running": True, "message": "Bot started"})\n\n    async def stop(self) -> None:\n        if not self._running:\n            return\n        self._running = False\n        logger.info("Bot engine stopping…")\n        if self._loop_task:\n            self._loop_task.cancel()\n            try:\n                await self._loop_task\n            except asyncio.CancelledError:\n                pass\n        if self._stats_task:\n            self._stats_task.cancel()\n            try:\n                await self._stats_task\n            except asyncio.CancelledError:\n                pass\n        await self._emit_event("status", {"running": False, "message": "Bot stopped"})\n        logger.info("Bot engine stopped.")\n\n    @property\n    def is_running(self) -> bool:\n        return self._running\n\n    # ─── Main scan loop ───────────────────────────────────────────────────────\n\n    async def _main_loop(self) -> None:\n        logger.info("Main scan loop started. Interval=%ds", config.SCAN_INTERVAL)\n        while self._running:\n            try:\n                await self._run_scan_cycle()\n            except asyncio.CancelledError:\n                raise\n            except Exception as exc:\n                logger.error("Unhandled error in main loop: %s", exc, exc_info=True)\n\n            # Sleep until next scan\n            try:\n                await asyncio.sleep(config.SCAN_INTERVAL)\n            except asyncio.CancelledError:\n                raise\n\n    async def _run_scan_cycle(self) -> None:\n        """One complete scan → detect → trade cycle."""\n        cycle_start = time.time()\n\n        # 1. Refresh portfolio value for sizing decisions\n        balance = await self.scanner.get_balance()\n        self.detector.update_portfolio_value(balance)\n        self.risk_manager.update_portfolio_value(balance)\n\n        # 2. Check stop-loss\n        if self.risk_manager.stop_loss_check():\n            logger.critical("Stop-loss triggered – halting trading.")\n            await self._emit_event("alert", {"level": "critical", "message": "Stop-loss triggered!"})\n            await self.stop()\n            return\n\n        # 3. Scan markets\n        markets = await self.scanner.scan_once()\n        if not markets:\n            logger.warning("No markets returned from scanner.")\n            return\n\n        # 4. Detect opportunities\n        opportunities = self.detector.detect(markets)\n        self._opportunities_found += len(opportunities)\n\n        if opportunities:\n            await self._emit_event(\n                "opportunities",\n                {"count": len(opportunities), "items": [o.as_dict() for o in opportunities[:5]]},\n            )\n\n        # 5. Save opportunities to DB and attempt to execute\n        for opp in opportunities:\n            opp_id = await db.save_opportunity(\n                market_id=opp.market_id,\n                question=opp.question,\n                yes_price=opp.yes_price,\n                no_price=opp.no_price,\n                spread=opp.spread,\n                potential_profit_pct=opp.profit_pct,\n            )\n\n            # Risk check\n            risk_result = self.risk_manager.check_opportunity(\n                market_id=opp.market_id,\n                profit_pct=opp.profit_pct,\n                requested_size=opp.recommended_size,\n            )\n\n            if not risk_result.approved:\n                logger.info("Risk rejected opportunity %s: %s", opp.market_id, risk_result.reason)\n                continue\n\n            # Execute trade\n            trade_id = await self.trader.execute_arbitrage(opp, risk_result.approved_size)\n            if trade_id is None:\n                logger.warning("Trade execution failed for %s", opp.market_id)\n                continue\n\n            # Register with risk manager\n            total_cost = risk_result.approved_size\n            self.risk_manager.register_position(\n                trade_id=trade_id,\n                market_id=opp.market_id,\n                total_cost=total_cost,\n                expected_profit=opp.net_profit_per_unit * (total_cost / opp.net_cost),\n            )\n\n            # Mark opportunity as executed\n            await db.mark_opportunity_executed(opp_id, trade_id)\n\n            self._total_trades_opened += 1\n\n            await self._emit_event(\n                "trade_opened",\n                {"trade_id": trade_id, "market_id": opp.market_id, "question": opp.question[:80]},\n            )\n\n            # In mock mode, schedule async resolution\n            if config.MOCK_MODE:\n                asyncio.create_task(self._mock_resolve(trade_id))\n\n        elapsed = time.time() - cycle_start\n        logger.debug("Scan cycle completed in %.2fs | markets=%d opps=%d", elapsed, len(markets), len(opportunities))\n\n    async def _mock_resolve(self, trade_id: int) -> None:\n        """Resolve a mock trade after a simulated delay."""\n        try:\n            await self.trader.simulate_resolution(trade_id)\n            # After resolution update the risk manager\n            pos = self.trader.open_trades.get(trade_id)\n            # trade already removed from open_trades by simulate_resolution\n            # find from closed trades\n            trades = await db.get_trades(limit=1)\n            if trades:\n                latest = trades[0]\n                profit = latest.get("actual_profit", 0.0) or 0.0\n                self.risk_manager.close_position(trade_id, profit)\n                if profit > 0:\n                    self._winning_trades += 1\n                await self._emit_event(\n                    "trade_closed",\n                    {"trade_id": trade_id, "actual_profit": round(profit, 4)},\n                )\n        except Exception as exc:\n            logger.error("Error during mock resolution of trade %d: %s", trade_id, exc)\n\n    # ─── Stats snapshot loop ──────────────────────────────────────────────────\n\n    async def _stats_loop(self) -> None:\n        """Periodically save a bot stats snapshot to the database."""\n        while self._running:\n            try:\n                await asyncio.sleep(60)   # snapshot every 60 seconds\n                await self._snapshot_stats()\n            except asyncio.CancelledError:\n                raise\n            except Exception as exc:\n                logger.error("Stats loop error: %s", exc)\n\n    async def _snapshot_stats(self) -> None:\n        """Write a BotStats row to the database."""\n        balance = await self.scanner.get_balance()\n        pnl = self.trader.total_pnl\n        portfolio_value = balance + pnl\n\n        await db.save_bot_stats(\n            total_pnl=pnl,\n            total_trades=self._total_trades_opened,\n            winning_trades=self._winning_trades,\n            portfolio_value=portfolio_value,\n            opportunities_found=self._opportunities_found,\n        )\n        logger.debug(\n            "Stats snapshot: pnl=%.4f trades=%d opps=%d",\n            pnl, self._total_trades_opened, self._opportunities_found,\n        )\n\n    # ─── Event emission ───────────────────────────────────────────────────────\n\n    async def _emit_event(self, event_type: str, data: Dict[str, Any]) -> None:\n        payload = {"type": event_type, "data": data, "ts": time.time()}\n        try:\n            self.event_queue.put_nowait(payload)\n        except asyncio.QueueFull:\n            logger.debug("Event queue full; dropping event %s", event_type)\n\n    # ─── Status summary ───────────────────────────────────────────────────────\n\n    async def get_status(self) -> Dict[str, Any]:\n        balance = await self.scanner.get_balance()\n        risk = self.risk_manager.summary()\n        return {\n            "running": self._running,\n            "mock_mode": config.MOCK_MODE,\n            "uptime_seconds": round(time.time() - self._start_time, 1) if self._start_time else 0,\n            "balance": round(balance, 2),\n            "total_pnl": round(self.trader.total_pnl, 4),\n            "total_trades": self._total_trades_opened,\n            "winning_trades": self._winning_trades,\n            "win_rate": round(\n                (self._winning_trades / self._total_trades_opened * 100)\n                if self._total_trades_opened > 0 else 0.0,\n                1,\n            ),\n            "open_positions": risk["open_positions"],\n            "total_exposure": risk["total_exposure"],\n            "opportunities_found_session": self._opportunities_found,\n            "scan_count": self.scanner.scan_count,\n            "scan_interval": config.SCAN_INTERVAL,\n        }\n'

FILES['bot/risk_manager.py'] = '"""\nRisk manager for Polymarket Arbitrage Bot.\nEnforces position limits, exposure caps, Kelly sizing, and stop-loss logic.\n"""\n\nimport logging\nfrom dataclasses import dataclass, field\nfrom typing import Dict, List, Optional\n\nfrom config import config\n\nlogger = logging.getLogger(__name__)\n\n\n@dataclass\nclass RiskCheckResult:\n    """Outcome of a risk pre-check."""\n    approved: bool\n    reason: str\n    approved_size: float = 0.0   # adjusted (possibly reduced) position size in USD\n\n\n@dataclass\nclass PositionRecord:\n    """Lightweight view of an open position for exposure tracking."""\n    trade_id: int\n    market_id: str\n    total_cost: float\n    expected_profit: float\n\n\nclass RiskManager:\n    """\n    Centralized risk gate that must approve every trade before execution.\n    """\n\n    def __init__(\n        self,\n        max_position_pct: float = None,\n        max_exposure_pct: float = None,\n        min_profit_pct: float = None,\n        max_concurrent_positions: int = None,\n        kelly_fraction: float = None,\n        fee_rate: float = None,\n    ):\n        self.max_position_pct = max_position_pct or config.MAX_POSITION_PCT\n        self.max_exposure_pct = max_exposure_pct or config.MAX_EXPOSURE_PCT\n        self.min_profit_pct = min_profit_pct or config.MIN_PROFIT_PCT\n        self.max_concurrent_positions = max_concurrent_positions or config.MAX_CONCURRENT_POSITIONS\n        self.kelly_fraction = kelly_fraction or config.KELLY_FRACTION\n        self.fee_rate = fee_rate or config.FEE_RATE\n\n        self._portfolio_value: float = config.INITIAL_PORTFOLIO\n        self._open_positions: Dict[int, PositionRecord] = {}   # trade_id → PositionRecord\n        self._total_pnl: float = 0.0\n\n    # ─── Portfolio value ──────────────────────────────────────────────────────\n\n    def update_portfolio_value(self, value: float) -> None:\n        self._portfolio_value = max(value, 0.01)\n\n    @property\n    def portfolio_value(self) -> float:\n        return self._portfolio_value\n\n    # ─── Position tracking ────────────────────────────────────────────────────\n\n    def register_position(self, trade_id: int, market_id: str, total_cost: float, expected_profit: float) -> None:\n        """Called after a trade is successfully opened."""\n        self._open_positions[trade_id] = PositionRecord(\n            trade_id=trade_id,\n            market_id=market_id,\n            total_cost=total_cost,\n            expected_profit=expected_profit,\n        )\n        logger.debug("Risk: registered position %d | cost=%.2f", trade_id, total_cost)\n\n    def close_position(self, trade_id: int, actual_profit: float) -> None:\n        """Called after a trade is closed/resolved."""\n        pos = self._open_positions.pop(trade_id, None)\n        if pos is None:\n            logger.warning("Risk: close_position called for unknown trade_id=%d", trade_id)\n            return\n        self._total_pnl += actual_profit\n        logger.debug(\n            "Risk: closed position %d | actual_profit=%.4f | cumulative_pnl=%.4f",\n            trade_id, actual_profit, self._total_pnl,\n        )\n\n    @property\n    def open_position_count(self) -> int:\n        return len(self._open_positions)\n\n    @property\n    def total_exposure(self) -> float:\n        return sum(p.total_cost for p in self._open_positions.values())\n\n    @property\n    def total_pnl(self) -> float:\n        return self._total_pnl\n\n    # ─── Risk checks ──────────────────────────────────────────────────────────\n\n    def check_opportunity(\n        self,\n        market_id: str,\n        profit_pct: float,\n        requested_size: float,\n    ) -> RiskCheckResult:\n        """\n        Validate whether we should trade an opportunity.\n        Returns RiskCheckResult with approved=True and the approved (possibly\n        reduced) size, or approved=False with a reason.\n        """\n\n        # 1. Profit threshold\n        if profit_pct < self.min_profit_pct:\n            return RiskCheckResult(\n                approved=False,\n                reason=f"Profit {profit_pct:.4f}% below minimum {self.min_profit_pct}%",\n            )\n\n        # 2. Max concurrent positions\n        if self.open_position_count >= self.max_concurrent_positions:\n            return RiskCheckResult(\n                approved=False,\n                reason=(\n                    f"Max concurrent positions reached "\n                    f"({self.open_position_count}/{self.max_concurrent_positions})"\n                ),\n            )\n\n        # 3. Already in this market?\n        if any(p.market_id == market_id for p in self._open_positions.values()):\n            return RiskCheckResult(\n                approved=False,\n                reason=f"Already have an open position in market {market_id}",\n            )\n\n        # 4. Maximum position size\n        max_size = self._portfolio_value * (self.max_position_pct / 100.0)\n        approved_size = min(requested_size, max_size)\n\n        # 5. Total exposure cap\n        remaining_exposure = (self._portfolio_value * (self.max_exposure_pct / 100.0)) - self.total_exposure\n        if remaining_exposure <= 0:\n            return RiskCheckResult(\n                approved=False,\n                reason=(\n                    f"Total exposure cap reached: "\n                    f"${self.total_exposure:.2f} / "\n                    f"${self._portfolio_value * self.max_exposure_pct / 100:.2f}"\n                ),\n            )\n        approved_size = min(approved_size, remaining_exposure)\n\n        # 6. Minimum viable size ($1)\n        if approved_size < 1.0:\n            return RiskCheckResult(\n                approved=False,\n                reason=f"Approved size ${approved_size:.2f} too small (minimum $1.00)",\n            )\n\n        logger.debug(\n            "Risk: APPROVED market=%s profit=%.4f%% size=$%.2f (requested=$%.2f)",\n            market_id, profit_pct, approved_size, requested_size,\n        )\n        return RiskCheckResult(approved=True, reason="ok", approved_size=approved_size)\n\n    def stop_loss_check(self) -> bool:\n        """\n        Returns True if trading should be halted due to excessive losses.\n        Trigger: total P&L < -20% of initial portfolio.\n        """\n        loss_threshold = -0.20 * config.INITIAL_PORTFOLIO\n        if self._total_pnl < loss_threshold:\n            logger.warning(\n                "STOP-LOSS triggered: total P&L=%.2f below threshold=%.2f",\n                self._total_pnl, loss_threshold,\n            )\n            return True\n        return False\n\n    # ─── Kelly position sizing ────────────────────────────────────────────────\n\n    def kelly_size(self, net_profit_per_unit: float, net_cost_per_unit: float) -> float:\n        """\n        Calculate the Kelly-optimal position size in USD.\n        For a risk-free arb (p=1), Kelly fraction = min(b, 1) * kelly_fraction.\n        b = fractional return = net_profit / net_cost.\n        """\n        if net_cost_per_unit <= 0:\n            return 0.0\n        b = net_profit_per_unit / net_cost_per_unit\n        raw_kelly = min(b, 1.0)\n        kelly_size = self._portfolio_value * self.kelly_fraction * raw_kelly\n        max_size = self._portfolio_value * (self.max_position_pct / 100.0)\n        return min(kelly_size, max_size)\n\n    # ─── Summary ─────────────────────────────────────────────────────────────\n\n    def summary(self) -> dict:\n        return {\n            "portfolio_value": round(self._portfolio_value, 2),\n            "total_pnl": round(self._total_pnl, 4),\n            "open_positions": self.open_position_count,\n            "total_exposure": round(self.total_exposure, 2),\n            "exposure_pct": round(\n                (self.total_exposure / self._portfolio_value) * 100\n                if self._portfolio_value > 0 else 0.0,\n                2,\n            ),\n            "max_concurrent_positions": self.max_concurrent_positions,\n            "stop_loss_triggered": self.stop_loss_check(),\n        }\n'

FILES['bot/scanner.py'] = '"""\nMarket scanner for Polymarket Arbitrage Bot.\nContinuously fetches active binary markets and caches the data with TTL.\n"""\n\nimport asyncio\nimport logging\nimport time\nfrom typing import Dict, List, Optional, Tuple\n\nfrom bot.client import create_client, MarketPrice\n\nlogger = logging.getLogger(__name__)\n\n\nclass MarketScanner:\n    """\n    Scans Polymarket for active binary (YES/NO) markets and returns\n    their current prices.  Results are cached with a configurable TTL\n    so we don\'t hammer the API on every scan iteration.\n    """\n\n    def __init__(self, cache_ttl: int = 15):\n        """\n        Args:\n            cache_ttl: Seconds before the market-price cache expires.\n        """\n        self.client = create_client()\n        self.cache_ttl = cache_ttl\n        self._cache: List[MarketPrice] = []\n        self._cache_ts: float = 0.0\n        self._scan_count: int = 0\n\n    # ─── Public API ───────────────────────────────────────────────────────────\n\n    async def get_markets(self) -> List[MarketPrice]:\n        """\n        Return the current list of active markets.\n        Uses the in-memory cache if it is still fresh.\n        """\n        if self._cache_is_fresh():\n            return self._cache\n\n        return await self._refresh_cache()\n\n    async def scan_once(self) -> List[MarketPrice]:\n        """\n        Force a fresh scan regardless of cache state, then return all markets.\n        """\n        self._cache_ts = 0.0   # invalidate cache\n        return await self.get_markets()\n\n    @property\n    def scan_count(self) -> int:\n        return self._scan_count\n\n    # ─── Internal helpers ─────────────────────────────────────────────────────\n\n    def _cache_is_fresh(self) -> bool:\n        return bool(self._cache) and (time.monotonic() - self._cache_ts) < self.cache_ttl\n\n    async def _refresh_cache(self) -> List[MarketPrice]:\n        """Fetch markets from the client and update the cache."""\n        logger.debug("Refreshing market cache…")\n        try:\n            markets = await self.client.get_markets()\n        except Exception as exc:\n            logger.error("Scanner: error fetching markets: %s", exc)\n            return self._cache  # return stale data rather than crashing\n\n        # Filter: active, not closed, has valid token IDs\n        active: List[MarketPrice] = [\n            m for m in markets\n            if _is_valid_binary_market(m)\n        ]\n\n        self._cache = active\n        self._cache_ts = time.monotonic()\n        self._scan_count += 1\n\n        logger.info(\n            "Scan #%d: %d active binary markets found (from %d total)",\n            self._scan_count,\n            len(active),\n            len(markets),\n        )\n        return active\n\n    # ─── Balance helper ───────────────────────────────────────────────────────\n\n    async def get_balance(self) -> float:\n        """Delegate to the underlying client."""\n        try:\n            return await self.client.get_balance()\n        except Exception as exc:\n            logger.error("Scanner: error fetching balance: %s", exc)\n            return 0.0\n\n\ndef _is_valid_binary_market(m: MarketPrice) -> bool:\n    """\n    Return True only if the MarketPrice looks like a live binary market\n    with sensible prices.\n    """\n    if not m.market_id:\n        return False\n    if not m.yes_token_id or not m.no_token_id:\n        return False\n    # Prices must be in (0, 1)\n    if not (0.0 < m.yes_ask < 1.0):\n        return False\n    if not (0.0 < m.no_ask < 1.0):\n        return False\n    return True\n'

FILES['bot/trader.py'] = '"""\nTrade executor for Polymarket Arbitrage Bot.\nTakes an ArbitrageOpportunity, executes both YES and NO legs,\ntracks open positions, and closes them when markets resolve.\n"""\n\nimport asyncio\nimport logging\nimport random\nimport time\nfrom typing import Dict, Optional\n\nfrom bot.arbitrage_detector import ArbitrageOpportunity\nfrom bot.client import create_client, OrderResult\nfrom bot import database as db\nfrom config import config\n\nlogger = logging.getLogger(__name__)\n\n\nclass Trader:\n    """\n    Executes arbitrage trades and tracks their lifecycle.\n    """\n\n    def __init__(self):\n        self.client = create_client()\n        # trade_id → dict with position metadata\n        self._open_trades: Dict[int, dict] = {}\n        self._closed_trades: int = 0\n        self._total_pnl: float = 0.0\n\n    # ─── Execute ──────────────────────────────────────────────────────────────\n\n    async def execute_arbitrage(\n        self,\n        opportunity: ArbitrageOpportunity,\n        position_size_usd: float,\n    ) -> Optional[int]:\n        """\n        Buy YES and NO tokens simultaneously.\n        Returns the database trade_id on success, None on failure.\n        """\n        yes_price = opportunity.yes_price\n        no_price = opportunity.no_price\n        net_cost_per_unit = yes_price + no_price\n\n        if net_cost_per_unit <= 0:\n            logger.error("Invalid net_cost_per_unit for %s", opportunity.market_id)\n            return None\n\n        # Number of contracts (units) to buy with the approved capital\n        units = position_size_usd / net_cost_per_unit\n        yes_size = round(units, 4)\n        no_size = round(units, 4)\n        total_cost = round(units * net_cost_per_unit, 6)\n        fees = round(total_cost * config.FEE_RATE, 6)\n        expected_profit = round(units * opportunity.net_profit_per_unit, 6)\n\n        logger.info(\n            "Executing arb on %s | units=%.4f YES@%.4f NO@%.4f cost=$%.2f expected_profit=$%.4f",\n            opportunity.market_id,\n            units,\n            yes_price,\n            no_price,\n            total_cost,\n            expected_profit,\n        )\n\n        # ── Place orders ──────────────────────────────────────────────────────\n        yes_result, no_result = await asyncio.gather(\n            self.client.place_order(\n                market_id=opportunity.market_id,\n                token_id=opportunity.yes_token_id,\n                side="BUY",\n                price=yes_price,\n                size=yes_size,\n            ),\n            self.client.place_order(\n                market_id=opportunity.market_id,\n                token_id=opportunity.no_token_id,\n                side="BUY",\n                price=no_price,\n                size=no_size,\n            ),\n        )\n\n        # ── Handle failures / partial fills ──────────────────────────────────\n        if yes_result.status == "CANCELLED" and no_result.status == "CANCELLED":\n            logger.error(\n                "Both legs cancelled for market %s – aborting", opportunity.market_id\n            )\n            return None\n\n        # Use actual filled sizes\n        actual_yes = yes_result.filled_size or yes_size\n        actual_no = no_result.filled_size or no_size\n        actual_cost = (\n            actual_yes * yes_price\n            + actual_no * no_price\n            + yes_result.fees_paid\n            + no_result.fees_paid\n        )\n        actual_expected_profit = (\n            min(actual_yes, actual_no) * (1.0 - net_cost_per_unit)\n            - (actual_cost * config.FEE_RATE)\n        )\n\n        if yes_result.status == "CANCELLED":\n            logger.warning("YES leg cancelled; cancelling NO leg too (partial fill risk)")\n            # In live mode we\'d cancel the NO order; in mock it\'s already filled\n            return None\n\n        if no_result.status == "CANCELLED":\n            logger.warning("NO leg cancelled; cancelling YES leg too (partial fill risk)")\n            return None\n\n        # ── Persist to DB ─────────────────────────────────────────────────────\n        try:\n            trade_id = await db.save_trade(\n                market_id=opportunity.market_id,\n                question=opportunity.question,\n                strategy="yes_no_arb",\n                yes_size=actual_yes,\n                no_size=actual_no,\n                yes_price=yes_price,\n                no_price=no_price,\n                total_cost=round(actual_cost, 4),\n                expected_profit=round(actual_expected_profit, 6),\n            )\n        except Exception as exc:\n            logger.error("Failed to save trade to DB: %s", exc)\n            return None\n\n        self._open_trades[trade_id] = {\n            "market_id": opportunity.market_id,\n            "question": opportunity.question,\n            "yes_token_id": opportunity.yes_token_id,\n            "no_token_id": opportunity.no_token_id,\n            "yes_size": actual_yes,\n            "no_size": actual_no,\n            "yes_price": yes_price,\n            "no_price": no_price,\n            "total_cost": actual_cost,\n            "expected_profit": actual_expected_profit,\n            "yes_order_id": yes_result.order_id,\n            "no_order_id": no_result.order_id,\n            "opened_at": time.time(),\n        }\n\n        logger.info(\n            "Trade %d opened for market %s | cost=$%.4f | expected_profit=$%.6f",\n            trade_id,\n            opportunity.market_id,\n            actual_cost,\n            actual_expected_profit,\n        )\n        return trade_id\n\n    # ─── Close / resolution ───────────────────────────────────────────────────\n\n    async def close_trade(\n        self,\n        trade_id: int,\n        actual_profit: float,\n        status: str = "closed",\n    ) -> None:\n        """\n        Mark a trade as closed in the database and update internal state.\n        """\n        pos = self._open_trades.pop(trade_id, None)\n        if pos is None:\n            logger.warning("close_trade: unknown trade_id=%d", trade_id)\n            return\n\n        try:\n            await db.close_trade(trade_id, actual_profit, status)\n        except Exception as exc:\n            logger.error("Failed to update trade %d in DB: %s", trade_id, exc)\n\n        self._total_pnl += actual_profit\n        self._closed_trades += 1\n\n        logger.info(\n            "Trade %d closed | actual_profit=$%.4f | cumulative_pnl=$%.4f",\n            trade_id,\n            actual_profit,\n            self._total_pnl,\n        )\n\n    async def simulate_resolution(self, trade_id: int) -> None:\n        """\n        Mock-mode only: randomly resolve the market after a short delay,\n        paying out 1.0 on the winning leg.\n        """\n        if not config.MOCK_MODE:\n            return\n\n        pos = self._open_trades.get(trade_id)\n        if pos is None:\n            return\n\n        # Simulate waiting for resolution (2–10 seconds in mock mode)\n        await asyncio.sleep(random.uniform(2, 10))\n\n        # In a real arb both outcomes yield profit; simulate the payout\n        winning_size = pos["yes_size"]  # either leg, same size in our arb\n        payout = winning_size * 1.0     # $1 per winning token\n        actual_profit = payout - pos["total_cost"]\n\n        await self.close_trade(trade_id, actual_profit)\n\n        if config.MOCK_MODE:\n            # Update mock balance\n            self.client.mock_credit(payout) if hasattr(self.client, "mock_credit") else None\n\n    # ─── Accessors ────────────────────────────────────────────────────────────\n\n    @property\n    def open_trades(self) -> Dict[int, dict]:\n        return dict(self._open_trades)\n\n    @property\n    def total_pnl(self) -> float:\n        return self._total_pnl\n\n    @property\n    def closed_trades(self) -> int:\n        return self._closed_trades\n'

FILES['config.py'] = '"""\nConfiguration module for Polymarket Arbitrage Bot.\nLoads settings from environment variables with sensible defaults.\n"""\n\nimport os\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\n\nclass Config:\n    """Central configuration class loaded from environment variables."""\n\n    # API Configuration\n    CLOB_API_URL: str = os.getenv("CLOB_API_URL", "https://clob.polymarket.com")\n    PRIVATE_KEY: str = os.getenv("PRIVATE_KEY", "")\n    CHAIN_ID: int = int(os.getenv("CHAIN_ID", "137"))\n    CLOB_API_KEY: str = os.getenv("CLOB_API_KEY", "")\n    CLOB_API_SECRET: str = os.getenv("CLOB_API_SECRET", "")\n    CLOB_API_PASSPHRASE: str = os.getenv("CLOB_API_PASSPHRASE", "")\n\n    # Trading Parameters\n    MIN_PROFIT_PCT: float = float(os.getenv("MIN_PROFIT_PCT", "0.5"))\n    MAX_POSITION_PCT: float = float(os.getenv("MAX_POSITION_PCT", "5.0"))\n    MAX_EXPOSURE_PCT: float = float(os.getenv("MAX_EXPOSURE_PCT", "50.0"))\n    MAX_CONCURRENT_POSITIONS: int = int(os.getenv("MAX_CONCURRENT_POSITIONS", "10"))\n    FEE_RATE: float = float(os.getenv("FEE_RATE", "0.02"))\n\n    # Mode\n    MOCK_MODE: bool = os.getenv("MOCK_MODE", "true").lower() in ("true", "1", "yes")\n\n    # Dashboard\n    DASHBOARD_PORT: int = int(os.getenv("DASHBOARD_PORT", "8080"))\n    DASHBOARD_HOST: str = os.getenv("DASHBOARD_HOST", "0.0.0.0")\n\n    # Database\n    DATABASE_URL: str = os.getenv(\n        "DATABASE_URL", "sqlite+aiosqlite:///./polymarket_bot.db"\n    )\n\n    # Logging\n    LOG_LEVEL: str = os.getenv("LOG_LEVEL", "INFO")\n\n    # Scanning\n    SCAN_INTERVAL: int = int(os.getenv("SCAN_INTERVAL", "30"))\n\n    # Portfolio\n    INITIAL_PORTFOLIO: float = float(os.getenv("INITIAL_PORTFOLIO", "1000.0"))\n\n    # Kelly criterion fraction (fraction of full Kelly to use, 0.25 = quarter Kelly)\n    KELLY_FRACTION: float = float(os.getenv("KELLY_FRACTION", "0.25"))\n\n    # Minimum spread to consider (absolute, not percentage)\n    MIN_SPREAD: float = float(os.getenv("MIN_SPREAD", "0.005"))\n\n    @classmethod\n    def validate(cls) -> None:\n        """Validate critical configuration settings."""\n        if not cls.MOCK_MODE and not cls.PRIVATE_KEY:\n            raise ValueError(\n                "PRIVATE_KEY must be set when MOCK_MODE is false. "\n                "Set MOCK_MODE=true for testing without real funds."\n            )\n        if cls.MIN_PROFIT_PCT < 0:\n            raise ValueError("MIN_PROFIT_PCT must be non-negative.")\n        if not (0 < cls.MAX_POSITION_PCT <= 100):\n            raise ValueError("MAX_POSITION_PCT must be between 0 and 100.")\n        if not (0 < cls.MAX_EXPOSURE_PCT <= 100):\n            raise ValueError("MAX_EXPOSURE_PCT must be between 0 and 100.")\n        if not (0 <= cls.FEE_RATE < 1):\n            raise ValueError("FEE_RATE must be between 0 and 1.")\n\n    @classmethod\n    def summary(cls) -> dict:\n        """Return a safe summary (no secrets) of current config."""\n        return {\n            "clob_api_url": cls.CLOB_API_URL,\n            "chain_id": cls.CHAIN_ID,\n            "mock_mode": cls.MOCK_MODE,\n            "min_profit_pct": cls.MIN_PROFIT_PCT,\n            "max_position_pct": cls.MAX_POSITION_PCT,\n            "max_exposure_pct": cls.MAX_EXPOSURE_PCT,\n            "max_concurrent_positions": cls.MAX_CONCURRENT_POSITIONS,\n            "fee_rate": cls.FEE_RATE,\n            "scan_interval": cls.SCAN_INTERVAL,\n            "dashboard_port": cls.DASHBOARD_PORT,\n            "initial_portfolio": cls.INITIAL_PORTFOLIO,\n            "kelly_fraction": cls.KELLY_FRACTION,\n        }\n\n\nconfig = Config()\n'

FILES['dashboard/__init__.py'] = '"""Polymarket Arbitrage Bot - Web Dashboard package."""\n'

FILES['dashboard/app.py'] = '"""\nFastAPI web dashboard for Polymarket Arbitrage Bot.\nProvides REST API endpoints and real-time SSE updates.\n"""\n\nimport asyncio\nimport json\nimport logging\nimport time\nfrom typing import AsyncGenerator, Optional\n\nfrom fastapi import FastAPI, Request, HTTPException\nfrom fastapi.responses import HTMLResponse, StreamingResponse, JSONResponse\nfrom fastapi.staticfiles import StaticFiles\nfrom fastapi.templating import Jinja2Templates\n\nfrom bot import database as db\nfrom config import config\n\nlogger = logging.getLogger(__name__)\n\n# These are injected at startup by main.py\n_bot_engine = None\n_event_queue: Optional[asyncio.Queue] = None\n\napp = FastAPI(title="Polymarket Arbitrage Bot", version="1.0.0")\n\n# Templates\nimport os\n_template_dir = os.path.join(os.path.dirname(__file__), "templates")\ntemplates = Jinja2Templates(directory=_template_dir)\n\n# ─── Dependency injection helpers ────────────────────────────────────────────\n\ndef set_engine(engine, queue: asyncio.Queue) -> None:\n    global _bot_engine, _event_queue\n    _bot_engine = engine\n    _event_queue = queue\n\n\ndef get_engine():\n    if _bot_engine is None:\n        raise HTTPException(status_code=503, detail="Bot engine not initialised")\n    return _bot_engine\n\n\n# ─── HTML Dashboard ───────────────────────────────────────────────────────────\n\n@app.get("/", response_class=HTMLResponse)\nasync def dashboard(request: Request):\n    return templates.TemplateResponse("index.html", {"request": request})\n\n\n# ─── API: Bot Control ─────────────────────────────────────────────────────────\n\n@app.post("/api/bot/start")\nasync def start_bot():\n    engine = get_engine()\n    if engine.is_running:\n        return {"status": "already_running", "message": "Bot is already running"}\n    await engine.start()\n    return {"status": "started", "message": "Bot started successfully"}\n\n\n@app.post("/api/bot/stop")\nasync def stop_bot():\n    engine = get_engine()\n    if not engine.is_running:\n        return {"status": "already_stopped", "message": "Bot is not running"}\n    await engine.stop()\n    return {"status": "stopped", "message": "Bot stopped successfully"}\n\n\n# ─── API: Stats ───────────────────────────────────────────────────────────────\n\n@app.get("/api/stats")\nasync def get_stats():\n    engine = get_engine()\n    try:\n        live_status = await engine.get_status()\n    except Exception as exc:\n        logger.error("get_stats error: %s", exc)\n        live_status = {}\n\n    # Merge with latest DB snapshot\n    db_stats = await db.get_latest_stats() or {}\n    opps_today = await db.count_opportunities_today()\n    stats_history = await db.get_stats_history(limit=50)\n\n    return {\n        "live": live_status,\n        "snapshot": db_stats,\n        "opportunities_today": opps_today,\n        "pnl_history": stats_history,\n        "config": config.summary(),\n    }\n\n\n# ─── API: Opportunities ───────────────────────────────────────────────────────\n\n@app.get("/api/opportunities")\nasync def get_opportunities(limit: int = 50):\n    rows = await db.get_recent_opportunities(limit=min(limit, 200))\n    return {"opportunities": rows, "count": len(rows)}\n\n\n# ─── API: Trades ─────────────────────────────────────────────────────────────\n\n@app.get("/api/trades")\nasync def get_trades(limit: int = 100):\n    rows = await db.get_trades(limit=min(limit, 500))\n    return {"trades": rows, "count": len(rows)}\n\n\n# ─── API: Open Positions ─────────────────────────────────────────────────────\n\n@app.get("/api/positions")\nasync def get_positions():\n    rows = await db.get_open_trades()\n    engine = get_engine()\n\n    # Augment with in-memory P&L estimate\n    in_memory = engine.trader.open_trades if hasattr(engine, "trader") else {}\n    for row in rows:\n        tid = row.get("id")\n        mem = in_memory.get(tid, {})\n        row["unrealised_pnl"] = round(mem.get("expected_profit", row.get("expected_profit", 0)), 4)\n\n    return {"positions": rows, "count": len(rows)}\n\n\n# ─── API: SSE Events ─────────────────────────────────────────────────────────\n\n@app.get("/api/events")\nasync def sse_events(request: Request):\n    """Server-Sent Events stream for real-time dashboard updates."""\n\n    async def event_generator() -> AsyncGenerator[str, None]:\n        # Send an initial ping\n        yield "data: {\\"type\\": \\"ping\\"}\\n\\n"\n\n        last_ping = time.time()\n        while True:\n            if await request.is_disconnected():\n                break\n\n            # Send keep-alive ping every 15 s\n            if time.time() - last_ping > 15:\n                yield "data: {\\"type\\": \\"ping\\"}\\n\\n"\n                last_ping = time.time()\n\n            # Drain the event queue\n            try:\n                event = _event_queue.get_nowait() if _event_queue else None\n                if event:\n                    yield f"data: {json.dumps(event)}\\n\\n"\n                    continue\n            except asyncio.QueueEmpty:\n                pass\n\n            await asyncio.sleep(0.5)\n\n    return StreamingResponse(\n        event_generator(),\n        media_type="text/event-stream",\n        headers={\n            "Cache-Control": "no-cache",\n            "X-Accel-Buffering": "no",\n        },\n    )\n'

FILES['dashboard/templates/index.html'] = '<!DOCTYPE html>\n<html lang="en" data-bs-theme="dark">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>Polymarket Arbitrage Bot</title>\n\n  <!-- Bootstrap 5 dark -->\n  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet" />\n  <!-- Bootstrap Icons -->\n  <link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet" />\n  <!-- Chart.js -->\n  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.2/dist/chart.umd.min.js"></script>\n\n  <style>\n    :root {\n      --poly-green: #00c896;\n      --poly-red:   #ff4d6d;\n      --poly-blue:  #4e9eff;\n      --card-bg:    #1a1d23;\n      --border-col: #2d3140;\n    }\n    body { background: #0f1117; font-family: \'Inter\', system-ui, sans-serif; }\n\n    /* ── Header ── */\n    .navbar { background: #13161e !important; border-bottom: 1px solid var(--border-col); }\n    .navbar-brand { font-weight: 700; letter-spacing: 0.03em; color: var(--poly-green) !important; }\n    .status-badge { font-size: 0.75rem; font-weight: 600; border-radius: 20px; padding: 0.25rem 0.75rem; }\n    .status-running { background: rgba(0,200,150,0.15); color: var(--poly-green); }\n    .status-stopped { background: rgba(255,77,109,0.15); color: var(--poly-red); }\n\n    /* ── Stat cards ── */\n    .stat-card {\n      background: var(--card-bg);\n      border: 1px solid var(--border-col);\n      border-radius: 14px;\n      padding: 1.25rem 1.5rem;\n      transition: transform 0.15s;\n    }\n    .stat-card:hover { transform: translateY(-2px); }\n    .stat-label { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.08em; color: #6c757d; }\n    .stat-value { font-size: 2rem; font-weight: 700; line-height: 1.1; margin-top: 0.25rem; }\n    .stat-icon { font-size: 1.6rem; opacity: 0.7; }\n    .text-profit { color: var(--poly-green) !important; }\n    .text-loss   { color: var(--poly-red) !important; }\n\n    /* ── Panels ── */\n    .panel {\n      background: var(--card-bg);\n      border: 1px solid var(--border-col);\n      border-radius: 14px;\n      overflow: hidden;\n    }\n    .panel-header {\n      background: #13161e;\n      padding: 0.9rem 1.25rem;\n      font-weight: 600;\n      font-size: 0.9rem;\n      letter-spacing: 0.04em;\n      border-bottom: 1px solid var(--border-col);\n      display: flex; align-items: center; gap: 0.5rem;\n    }\n    .panel-body { padding: 0; }\n\n    /* ── Tables ── */\n    .table { margin: 0; font-size: 0.84rem; }\n    .table th { background: #13161e; color: #8b95a3; font-size: 0.73rem; text-transform: uppercase; letter-spacing: 0.07em; border-bottom: 1px solid var(--border-col); padding: 0.6rem 1rem; }\n    .table td { border-bottom: 1px solid #1e2130; padding: 0.6rem 1rem; vertical-align: middle; }\n    .table tbody tr:hover { background: rgba(255,255,255,0.03); }\n    .table tbody tr:last-child td { border-bottom: none; }\n\n    /* ── Badges ── */\n    .badge-open      { background: rgba(78,158,255,0.15); color: var(--poly-blue); }\n    .badge-closed    { background: rgba(0,200,150,0.15); color: var(--poly-green); }\n    .badge-cancelled { background: rgba(255,77,109,0.15); color: var(--poly-red); }\n    .badge-executed  { background: rgba(0,200,150,0.12); color: var(--poly-green); }\n    .badge-pending   { background: rgba(255,193,7,0.15);  color: #ffc107; }\n\n    /* ── Chart ── */\n    .chart-container { padding: 1rem 1.25rem; }\n\n    /* ── Misc ── */\n    .mock-banner {\n      background: rgba(255,193,7,0.12);\n      border-bottom: 1px solid rgba(255,193,7,0.3);\n      color: #ffc107;\n      font-size: 0.8rem; text-align: center; padding: 0.4rem;\n    }\n    .last-update { font-size: 0.72rem; color: #555; margin-top: 0.25rem; }\n    .spinner-sm { width: 0.8rem; height: 0.8rem; }\n    .truncate { max-width: 280px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n    @media (max-width: 768px) { .stat-value { font-size: 1.5rem; } }\n  </style>\n</head>\n<body>\n\n<!-- Mock mode banner (hidden by JS if not mock) -->\n<div id="mockBanner" class="mock-banner d-none">\n  <i class="bi bi-exclamation-triangle-fill me-1"></i>\n  MOCK MODE — Simulated data only. No real funds are being used.\n</div>\n\n<!-- ── Navbar ── -->\n<nav class="navbar navbar-expand-lg sticky-top">\n  <div class="container-fluid px-4">\n    <span class="navbar-brand">\n      <i class="bi bi-graph-up-arrow me-2"></i>Polymarket Arb Bot\n    </span>\n    <div class="d-flex align-items-center gap-3">\n      <div id="lastUpdate" class="last-update">Connecting…</div>\n      <span id="statusBadge" class="status-badge status-stopped">\n        <i class="bi bi-circle-fill me-1" style="font-size:0.5rem"></i>Stopped\n      </span>\n      <button id="btnStart" class="btn btn-sm btn-success" onclick="startBot()">\n        <i class="bi bi-play-fill me-1"></i>Start\n      </button>\n      <button id="btnStop" class="btn btn-sm btn-danger" onclick="stopBot()">\n        <i class="bi bi-stop-fill me-1"></i>Stop\n      </button>\n    </div>\n  </div>\n</nav>\n\n<!-- ── Main Content ── -->\n<div class="container-fluid px-4 py-4">\n\n  <!-- Stat Cards -->\n  <div class="row g-3 mb-4">\n    <div class="col-6 col-md-3">\n      <div class="stat-card">\n        <div class="d-flex justify-content-between align-items-start">\n          <div>\n            <div class="stat-label">Total P&amp;L</div>\n            <div id="statPnl" class="stat-value text-profit">$0.00</div>\n          </div>\n          <i class="bi bi-currency-dollar stat-icon text-profit"></i>\n        </div>\n      </div>\n    </div>\n    <div class="col-6 col-md-3">\n      <div class="stat-card">\n        <div class="d-flex justify-content-between align-items-start">\n          <div>\n            <div class="stat-label">Win Rate</div>\n            <div id="statWinRate" class="stat-value" style="color:var(--poly-blue)">0%</div>\n          </div>\n          <i class="bi bi-trophy stat-icon" style="color:var(--poly-blue)"></i>\n        </div>\n      </div>\n    </div>\n    <div class="col-6 col-md-3">\n      <div class="stat-card">\n        <div class="d-flex justify-content-between align-items-start">\n          <div>\n            <div class="stat-label">Open Positions</div>\n            <div id="statOpenPos" class="stat-value" style="color:#c4a3e0">0</div>\n          </div>\n          <i class="bi bi-layers stat-icon" style="color:#c4a3e0"></i>\n        </div>\n      </div>\n    </div>\n    <div class="col-6 col-md-3">\n      <div class="stat-card">\n        <div class="d-flex justify-content-between align-items-start">\n          <div>\n            <div class="stat-label">Opportunities Today</div>\n            <div id="statOppsToday" class="stat-value" style="color:#ffc107">0</div>\n          </div>\n          <i class="bi bi-lightning-charge stat-icon" style="color:#ffc107"></i>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Secondary stats row -->\n  <div class="row g-3 mb-4">\n    <div class="col-6 col-md-2">\n      <div class="stat-card py-3">\n        <div class="stat-label">Portfolio Value</div>\n        <div id="statPortfolio" class="fw-semibold mt-1">$0.00</div>\n      </div>\n    </div>\n    <div class="col-6 col-md-2">\n      <div class="stat-card py-3">\n        <div class="stat-label">Total Trades</div>\n        <div id="statTotalTrades" class="fw-semibold mt-1">0</div>\n      </div>\n    </div>\n    <div class="col-6 col-md-2">\n      <div class="stat-card py-3">\n        <div class="stat-label">Total Exposure</div>\n        <div id="statExposure" class="fw-semibold mt-1">$0.00</div>\n      </div>\n    </div>\n    <div class="col-6 col-md-2">\n      <div class="stat-card py-3">\n        <div class="stat-label">Markets Scanned</div>\n        <div id="statScans" class="fw-semibold mt-1">0</div>\n      </div>\n    </div>\n    <div class="col-6 col-md-2">\n      <div class="stat-card py-3">\n        <div class="stat-label">Scan Interval</div>\n        <div id="statScanInterval" class="fw-semibold mt-1">30s</div>\n      </div>\n    </div>\n    <div class="col-6 col-md-2">\n      <div class="stat-card py-3">\n        <div class="stat-label">Uptime</div>\n        <div id="statUptime" class="fw-semibold mt-1">0s</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- P&L Chart -->\n  <div class="panel mb-4">\n    <div class="panel-header">\n      <i class="bi bi-graph-up text-success"></i> Live P&amp;L Chart\n    </div>\n    <div class="chart-container">\n      <canvas id="pnlChart" height="80"></canvas>\n    </div>\n  </div>\n\n  <!-- Opportunities + Positions row -->\n  <div class="row g-4 mb-4">\n\n    <!-- Opportunities -->\n    <div class="col-xl-7">\n      <div class="panel h-100">\n        <div class="panel-header">\n          <i class="bi bi-lightning-charge text-warning"></i>\n          Recent Opportunities\n          <span id="oppCount" class="ms-auto badge bg-secondary">0</span>\n        </div>\n        <div class="panel-body" style="overflow-x:auto; max-height:340px; overflow-y:auto">\n          <table class="table">\n            <thead>\n              <tr>\n                <th>Market</th>\n                <th>YES</th>\n                <th>NO</th>\n                <th>Spread</th>\n                <th>Est. Profit%</th>\n                <th>Status</th>\n              </tr>\n            </thead>\n            <tbody id="oppTable">\n              <tr><td colspan="6" class="text-center text-muted py-4">No opportunities yet</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n\n    <!-- Open Positions -->\n    <div class="col-xl-5">\n      <div class="panel h-100">\n        <div class="panel-header">\n          <i class="bi bi-layers text-info"></i>\n          Active Positions\n          <span id="posCount" class="ms-auto badge bg-secondary">0</span>\n        </div>\n        <div class="panel-body" style="overflow-x:auto; max-height:340px; overflow-y:auto">\n          <table class="table">\n            <thead>\n              <tr>\n                <th>Market</th>\n                <th>Cost</th>\n                <th>Exp. Profit</th>\n                <th>Opened</th>\n              </tr>\n            </thead>\n            <tbody id="posTable">\n              <tr><td colspan="4" class="text-center text-muted py-4">No open positions</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Trade History -->\n  <div class="panel mb-4">\n    <div class="panel-header">\n      <i class="bi bi-clock-history text-secondary"></i>\n      Trade History\n      <span id="tradeCount" class="ms-auto badge bg-secondary">0</span>\n    </div>\n    <div class="panel-body" style="overflow-x:auto; max-height:400px; overflow-y:auto">\n      <table class="table">\n        <thead>\n          <tr>\n            <th>#</th>\n            <th>Market</th>\n            <th>Strategy</th>\n            <th>Cost</th>\n            <th>Exp. Profit</th>\n            <th>Actual Profit</th>\n            <th>Status</th>\n            <th>Opened</th>\n          </tr>\n        </thead>\n        <tbody id="tradeTable">\n          <tr><td colspan="8" class="text-center text-muted py-4">No trades yet</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n</div><!-- /container -->\n\n<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script>\n<script>\n/* ════════════════════════════════════════════════════════════\n   Dashboard JS\n   ════════════════════════════════════════════════════════════ */\n\n// ── Chart setup ──────────────────────────────────────────────\nconst chartCtx = document.getElementById(\'pnlChart\').getContext(\'2d\');\nconst pnlChart = new Chart(chartCtx, {\n  type: \'line\',\n  data: {\n    labels: [],\n    datasets: [{\n      label: \'P&L ($)\',\n      data: [],\n      borderColor: \'#00c896\',\n      backgroundColor: \'rgba(0,200,150,0.07)\',\n      borderWidth: 2,\n      pointRadius: 2,\n      pointHoverRadius: 4,\n      tension: 0.4,\n      fill: true,\n    }]\n  },\n  options: {\n    responsive: true,\n    maintainAspectRatio: true,\n    interaction: { mode: \'index\', intersect: false },\n    plugins: {\n      legend: { display: false },\n      tooltip: {\n        backgroundColor: \'#1a1d23\',\n        borderColor: \'#2d3140\',\n        borderWidth: 1,\n        callbacks: {\n          label: ctx => ` P&L: $${ctx.parsed.y.toFixed(4)}`\n        }\n      }\n    },\n    scales: {\n      x: {\n        grid: { color: \'#1e2130\' },\n        ticks: { color: \'#6c757d\', maxTicksLimit: 8, font: { size: 10 } }\n      },\n      y: {\n        grid: { color: \'#1e2130\' },\n        ticks: {\n          color: \'#6c757d\',\n          font: { size: 10 },\n          callback: v => \'$\' + v.toFixed(2)\n        }\n      }\n    }\n  }\n});\n\n// ── State ─────────────────────────────────────────────────────\nlet botRunning = false;\n\n// ── Helpers ───────────────────────────────────────────────────\nfunction fmt$(v) { return v == null ? \'—\' : \'$\' + parseFloat(v).toFixed(4); }\nfunction fmtPct(v) { return v == null ? \'—\' : parseFloat(v).toFixed(3) + \'%\'; }\nfunction fmtTime(iso) {\n  if (!iso) return \'—\';\n  return new Date(iso).toLocaleTimeString();\n}\nfunction colorNum(v, el) {\n  const n = parseFloat(v);\n  el.classList.remove(\'text-profit\',\'text-loss\',\'text-muted\');\n  if (isNaN(n) || n === 0) el.classList.add(\'text-muted\');\n  else if (n > 0) el.classList.add(\'text-profit\');\n  else el.classList.add(\'text-loss\');\n}\nfunction statusBadge(s) {\n  const map = {\n    open:      \'<span class="badge badge-open">Open</span>\',\n    closed:    \'<span class="badge badge-closed">Closed</span>\',\n    cancelled: \'<span class="badge badge-cancelled">Cancelled</span>\',\n  };\n  return map[s] || `<span class="badge bg-secondary">${s}</span>`;\n}\nfunction truncate(s, n=55) { return s && s.length > n ? s.slice(0,n)+\'…\' : (s||\'—\'); }\n\nfunction fmtUptime(secs) {\n  if (!secs) return \'0s\';\n  const h = Math.floor(secs / 3600);\n  const m = Math.floor((secs % 3600) / 60);\n  const s = Math.floor(secs % 60);\n  if (h > 0) return `${h}h ${m}m`;\n  if (m > 0) return `${m}m ${s}s`;\n  return `${s}s`;\n}\n\n// ── Update stats ──────────────────────────────────────────────\nfunction updateStats(data) {\n  const live = data.live || {};\n  const snap = data.snapshot || {};\n\n  botRunning = live.running || false;\n  updateStatusBadge(botRunning);\n\n  // Mock banner\n  if (live.mock_mode) {\n    document.getElementById(\'mockBanner\').classList.remove(\'d-none\');\n  }\n\n  // Primary cards\n  const pnl = live.total_pnl ?? 0;\n  const pnlEl = document.getElementById(\'statPnl\');\n  pnlEl.textContent = \'$\' + parseFloat(pnl).toFixed(4);\n  colorNum(pnl, pnlEl);\n\n  const wr = live.win_rate ?? 0;\n  document.getElementById(\'statWinRate\').textContent = wr.toFixed(1) + \'%\';\n  document.getElementById(\'statOpenPos\').textContent = live.open_positions ?? 0;\n  document.getElementById(\'statOppsToday\').textContent = data.opportunities_today ?? 0;\n\n  // Secondary stats\n  document.getElementById(\'statPortfolio\').textContent = \'$\' + (live.balance ?? 0).toFixed(2);\n  document.getElementById(\'statTotalTrades\').textContent = live.total_trades ?? 0;\n  document.getElementById(\'statExposure\').textContent = \'$\' + (live.total_exposure ?? 0).toFixed(2);\n  document.getElementById(\'statScans\').textContent = live.scan_count ?? 0;\n  document.getElementById(\'statScanInterval\').textContent = (live.scan_interval ?? 30) + \'s\';\n  document.getElementById(\'statUptime\').textContent = fmtUptime(live.uptime_seconds ?? 0);\n\n  // P&L chart\n  const hist = data.pnl_history || [];\n  if (hist.length > 0) {\n    pnlChart.data.labels = hist.map(h => {\n      const d = new Date(h.timestamp);\n      return d.toLocaleTimeString([], {hour:\'2-digit\', minute:\'2-digit\'});\n    });\n    pnlChart.data.datasets[0].data = hist.map(h => h.total_pnl || 0);\n    pnlChart.update(\'none\');\n  }\n\n  document.getElementById(\'lastUpdate\').textContent = \'Updated \' + new Date().toLocaleTimeString();\n}\n\nfunction updateStatusBadge(running) {\n  const badge = document.getElementById(\'statusBadge\');\n  if (running) {\n    badge.className = \'status-badge status-running\';\n    badge.innerHTML = \'<i class="bi bi-circle-fill me-1" style="font-size:0.5rem"></i>Running\';\n  } else {\n    badge.className = \'status-badge status-stopped\';\n    badge.innerHTML = \'<i class="bi bi-circle-fill me-1" style="font-size:0.5rem"></i>Stopped\';\n  }\n  document.getElementById(\'btnStart\').disabled = running;\n  document.getElementById(\'btnStop\').disabled = !running;\n}\n\n// ── Opportunities ─────────────────────────────────────────────\nfunction updateOpportunities(opps) {\n  document.getElementById(\'oppCount\').textContent = opps.length;\n  const tbody = document.getElementById(\'oppTable\');\n  if (!opps.length) {\n    tbody.innerHTML = \'<tr><td colspan="6" class="text-center text-muted py-4">No opportunities yet</td></tr>\';\n    return;\n  }\n  tbody.innerHTML = opps.map(o => {\n    const profitColor = o.potential_profit_pct > 0 ? \'text-profit\' : \'text-muted\';\n    const execBadge = o.executed\n      ? \'<span class="badge badge-executed">Executed</span>\'\n      : \'<span class="badge badge-pending">Detected</span>\';\n    return `\n      <tr>\n        <td class="truncate" title="${o.question}">${truncate(o.question)}</td>\n        <td>${parseFloat(o.yes_price).toFixed(4)}</td>\n        <td>${parseFloat(o.no_price).toFixed(4)}</td>\n        <td>${parseFloat(o.spread).toFixed(4)}</td>\n        <td class="${profitColor} fw-semibold">${fmtPct(o.potential_profit_pct)}</td>\n        <td>${execBadge}</td>\n      </tr>`;\n  }).join(\'\');\n}\n\n// ── Positions ─────────────────────────────────────────────────\nfunction updatePositions(positions) {\n  document.getElementById(\'posCount\').textContent = positions.length;\n  const tbody = document.getElementById(\'posTable\');\n  if (!positions.length) {\n    tbody.innerHTML = \'<tr><td colspan="4" class="text-center text-muted py-4">No open positions</td></tr>\';\n    return;\n  }\n  tbody.innerHTML = positions.map(p => {\n    const pnlEl = parseFloat(p.unrealised_pnl ?? p.expected_profit ?? 0);\n    const pnlClass = pnlEl >= 0 ? \'text-profit\' : \'text-loss\';\n    return `\n      <tr>\n        <td class="truncate" title="${p.question}">${truncate(p.question, 40)}</td>\n        <td>${fmt$(p.total_cost)}</td>\n        <td class="${pnlClass} fw-semibold">${fmt$(pnlEl)}</td>\n        <td>${fmtTime(p.opened_at)}</td>\n      </tr>`;\n  }).join(\'\');\n}\n\n// ── Trade History ─────────────────────────────────────────────\nfunction updateTrades(trades) {\n  document.getElementById(\'tradeCount\').textContent = trades.length;\n  const tbody = document.getElementById(\'tradeTable\');\n  if (!trades.length) {\n    tbody.innerHTML = \'<tr><td colspan="8" class="text-center text-muted py-4">No trades yet</td></tr>\';\n    return;\n  }\n  tbody.innerHTML = trades.map(t => {\n    const ap = t.actual_profit;\n    const apClass = ap == null ? \'text-muted\' : (ap >= 0 ? \'text-profit\' : \'text-loss\');\n    return `\n      <tr>\n        <td class="text-muted">#${t.id}</td>\n        <td class="truncate" title="${t.question}">${truncate(t.question, 45)}</td>\n        <td><span class="badge bg-secondary">${t.strategy || \'yes_no_arb\'}</span></td>\n        <td>${fmt$(t.total_cost)}</td>\n        <td class="text-profit">${fmt$(t.expected_profit)}</td>\n        <td class="${apClass} fw-semibold">${ap != null ? fmt$(ap) : \'—\'}</td>\n        <td>${statusBadge(t.status)}</td>\n        <td class="text-muted">${fmtTime(t.opened_at)}</td>\n      </tr>`;\n  }).join(\'\');\n}\n\n// ── Data fetching ─────────────────────────────────────────────\nasync function fetchAll() {\n  try {\n    const [statsRes, oppsRes, posRes, tradeRes] = await Promise.all([\n      fetch(\'/api/stats\'),\n      fetch(\'/api/opportunities?limit=30\'),\n      fetch(\'/api/positions\'),\n      fetch(\'/api/trades?limit=50\'),\n    ]);\n    const [stats, opps, pos, trades] = await Promise.all([\n      statsRes.json(), oppsRes.json(), posRes.json(), tradeRes.json()\n    ]);\n    updateStats(stats);\n    updateOpportunities(opps.opportunities || []);\n    updatePositions(pos.positions || []);\n    updateTrades(trades.trades || []);\n  } catch(e) {\n    console.warn(\'fetch error:\', e);\n  }\n}\n\n// ── Bot control ───────────────────────────────────────────────\nasync function startBot() {\n  document.getElementById(\'btnStart\').disabled = true;\n  try {\n    await fetch(\'/api/bot/start\', { method: \'POST\' });\n    await fetchAll();\n  } catch(e) { console.error(e); document.getElementById(\'btnStart\').disabled = false; }\n}\nasync function stopBot() {\n  document.getElementById(\'btnStop\').disabled = true;\n  try {\n    await fetch(\'/api/bot/stop\', { method: \'POST\' });\n    await fetchAll();\n  } catch(e) { console.error(e); document.getElementById(\'btnStop\').disabled = false; }\n}\n\n// ── SSE for real-time updates ─────────────────────────────────\nfunction connectSSE() {\n  const es = new EventSource(\'/api/events\');\n  es.onmessage = (e) => {\n    try {\n      const msg = JSON.parse(e.data);\n      if (msg.type === \'ping\') return;\n      // On any relevant event, refresh data\n      if ([\'trade_opened\',\'trade_closed\',\'opportunities\',\'status\'].includes(msg.type)) {\n        fetchAll();\n      }\n    } catch(_) {}\n  };\n  es.onerror = () => {\n    // Reconnect after 5 s\n    es.close();\n    setTimeout(connectSSE, 5000);\n  };\n}\n\n// ── Init ──────────────────────────────────────────────────────\nfetchAll();\nconnectSSE();\n// Polling fallback every 5 s\nsetInterval(fetchAll, 5000);\n</script>\n</body>\n</html>\n'

FILES['main.py'] = '"""\nEntry point for Polymarket Arbitrage Bot.\nStarts the bot engine and the FastAPI dashboard together.\n"""\n\nimport argparse\nimport asyncio\nimport logging\nimport os\nimport signal\nimport sys\n\nimport uvicorn\nfrom dotenv import load_dotenv\n\n# Load .env before importing anything else\nload_dotenv()\n\nfrom config import config\nfrom bot import database as db\nfrom bot.engine import BotEngine\nfrom dashboard.app import app as dashboard_app, set_engine\n\n\ndef setup_logging(level: str = "INFO") -> None:\n    fmt = "%(asctime)s [%(levelname)s] %(name)s: %(message)s"\n    logging.basicConfig(\n        level=getattr(logging, level.upper(), logging.INFO),\n        format=fmt,\n        handlers=[logging.StreamHandler(sys.stdout)],\n    )\n    # Quiet noisy libs\n    logging.getLogger("uvicorn.access").setLevel(logging.WARNING)\n    logging.getLogger("sqlalchemy.engine").setLevel(logging.WARNING)\n    logging.getLogger("httpx").setLevel(logging.WARNING)\n\n\nlogger = logging.getLogger(__name__)\n\n\ndef parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser(description="Polymarket Arbitrage Bot")\n    parser.add_argument(\n        "--mock",\n        action="store_true",\n        default=None,\n        help="Force mock mode (overrides MOCK_MODE env var)",\n    )\n    parser.add_argument(\n        "--port",\n        type=int,\n        default=None,\n        help="Dashboard port (overrides DASHBOARD_PORT env var)",\n    )\n    parser.add_argument(\n        "--host",\n        type=str,\n        default=None,\n        help="Dashboard host (overrides DASHBOARD_HOST env var)",\n    )\n    parser.add_argument(\n        "--no-autostart",\n        action="store_true",\n        help="Do not automatically start the trading bot on launch",\n    )\n    parser.add_argument(\n        "--log-level",\n        type=str,\n        default=None,\n        help="Logging level (DEBUG, INFO, WARNING, ERROR)",\n    )\n    return parser.parse_args()\n\n\nasync def run(\n    host: str,\n    port: int,\n    autostart: bool = True,\n) -> None:\n    """Main async entry point."""\n\n    # ── Database ──────────────────────────────────────────────────────────────\n    logger.info("Initialising database…")\n    await db.init_database()\n    logger.info("Database ready.")\n\n    # ── Bot engine ────────────────────────────────────────────────────────────\n    event_queue: asyncio.Queue = asyncio.Queue(maxsize=1000)\n    engine = BotEngine(event_queue=event_queue)\n    set_engine(engine, event_queue)\n\n    if autostart:\n        logger.info("Auto-starting bot engine…")\n        await engine.start()\n\n    # ── Uvicorn server ────────────────────────────────────────────────────────\n    uv_config = uvicorn.Config(\n        app=dashboard_app,\n        host=host,\n        port=port,\n        log_level="warning",\n        loop="asyncio",\n    )\n    server = uvicorn.Server(uv_config)\n\n    # ── Graceful shutdown ─────────────────────────────────────────────────────\n    loop = asyncio.get_event_loop()\n\n    def _handle_signal():\n        logger.info("Shutdown signal received…")\n        server.should_exit = True\n\n    for sig in (signal.SIGINT, signal.SIGTERM):\n        try:\n            loop.add_signal_handler(sig, _handle_signal)\n        except NotImplementedError:\n            # Windows doesn\'t support add_signal_handler\n            pass\n\n    # ── Start serving ─────────────────────────────────────────────────────────\n    logger.info(\n        "Dashboard available at http://%s:%d  (mock_mode=%s)",\n        host if host != "0.0.0.0" else "localhost",\n        port,\n        config.MOCK_MODE,\n    )\n\n    try:\n        await server.serve()\n    finally:\n        logger.info("Shutting down bot engine…")\n        await engine.stop()\n        logger.info("Goodbye.")\n\n\ndef main() -> None:\n    args = parse_args()\n\n    # Apply CLI overrides before Config is used\n    if args.mock:\n        os.environ["MOCK_MODE"] = "true"\n        # Re-read the class attribute\n        config.__class__.MOCK_MODE = True\n\n    if args.port:\n        os.environ["DASHBOARD_PORT"] = str(args.port)\n        config.__class__.DASHBOARD_PORT = args.port\n\n    if args.host:\n        os.environ["DASHBOARD_HOST"] = args.host\n        config.__class__.DASHBOARD_HOST = args.host\n\n    log_level = args.log_level or config.LOG_LEVEL\n    setup_logging(log_level)\n\n    logger.info("=" * 60)\n    logger.info("  Polymarket Arbitrage Bot")\n    logger.info("  Mock mode : %s", config.MOCK_MODE)\n    logger.info("  Dashboard : http://%s:%d", config.DASHBOARD_HOST, config.DASHBOARD_PORT)\n    logger.info("=" * 60)\n\n    # Validate config\n    try:\n        config.validate()\n    except ValueError as exc:\n        logger.critical("Configuration error: %s", exc)\n        sys.exit(1)\n\n    autostart = not args.no_autostart\n\n    asyncio.run(\n        run(\n            host=config.DASHBOARD_HOST,\n            port=config.DASHBOARD_PORT,\n            autostart=autostart,\n        )\n    )\n\n\nif __name__ == "__main__":\n    main()\n'

